        "name": "Applications Demo",
        "code": "#!/usr/bin/env python3\n\"\"\"\nApplications of Tropical Closure-Capacity Duality.\n\n1. Access structure compression for secret sharing\n2. Feature selection via tropical dominance\n3. Network vulnerability analysis\n\"\"\"\n\nfrom itertools import combinations\nfrom typing import FrozenSet, Set, List, Dict\nimport random\n\n\ndef powerset(s: set) -> list:\n    elems = list(s)\n    result = []\n    for r in range(len(elems) + 1):\n        for combo in combinations(elems, r):\n            result.append(frozenset(combo))\n    return result\n\n\n# ============================================================\n# Application 1: Access Structure Compression\n# ============================================================\n\ndef access_structure_demo():\n    \"\"\"\n    Demonstrate access structure compression via tropical skeletons.\n\n    Scenario: 5 participants, threshold 3 (any 3 can reconstruct secret).\n    The access structure closure has many authorized sets, but the\n    tropical skeleton identifies the minimal essential participants.\n    \"\"\"\n    print(\"=\" * 60)\n    print(\"APPLICATION 1: Access Structure Compression\")\n    print(\"=\" * 60)\n\n    n = 5\n    threshold = 3\n    participants = set(range(n))\n\n    # Threshold closure: cl(S) = universe if |S| >= threshold, else S\n    def threshold_cl(s):\n        s = frozenset(s)\n        if len(s) >= threshold:\n            return frozenset(participants)\n        return s\n\n    # Count authorized sets (|S| >= threshold)\n    authorized = [s for s in powerset(participants) if len(s) >= threshold]\n    print(f\"\\nParticipants: {n}\")\n    print(f\"Threshold: {threshold}\")\n    print(f\"Authorized sets: {len(authorized)}\")\n\n    # Find skeleton\n    G = set(participants)\n    full_cl = threshold_cl(frozenset(G))\n    for g in sorted(G.copy()):\n        if threshold_cl(frozenset(G - {g})) == full_cl:\n            G.remove(g)\n    skeleton = frozenset(G)\n\n    print(f\"Canonical skeleton: {set(skeleton)} (size {len(skeleton)})\")\n    print(f\"Compression ratio: {len(authorized)} \u2192 {len(skeleton)} \"\n          f\"({len(skeleton)/len(authorized)*100:.1f}%)\")\n\n    # Any threshold-many elements from skeleton generate everything\n    print(f\"\\nSkeleton generates universe: \"\n          f\"{threshold_cl(skeleton) == frozenset(participants)}\")\n\n\n# ============================================================\n# Application 2: Feature Selection\n# ============================================================\n\ndef feature_selection_demo():\n    \"\"\"\n    Feature selection via tropical dominance.\n\n    Scenario: 6 features where some are derivable from others.\n    Features 4 and 5 are redundant given features {0,1,2,3}.\n    \"\"\"\n    print(\"\\n\" + \"=\" * 60)\n    print(\"APPLICATION 2: Feature Selection via Tropical Dominance\")\n    print(\"=\" * 60)\n\n    features = set(range(6))\n\n    # Feature dependency closure:\n    # Feature 4 = f(feature 0, feature 1)\n    # Feature 5 = f(feature 2, feature 3)\n    def feature_cl(s):\n        s = frozenset(s)\n        result = set(s)\n        if 0 in result and 1 in result:\n            result.add(4)\n        if 2 in result and 3 in result:\n            result.add(5)\n        return frozenset(result)\n\n    def feature_cap(s):\n        return 0 if len(frozenset(s)) == 0 else 1\n\n    print(f\"\\nFeatures: {features}\")\n\n    # Check which features are redundant\n    print(\"\\n--- Feature Redundancy Analysis ---\")\n    for x in sorted(features):\n        others = features - {x}\n        if x in feature_cl(frozenset(others)):\n            # Find minimal generating set\n            for size in range(1, len(others) + 1):\n                for combo in combinations(sorted(others), size):\n                    if x in feature_cl(frozenset(combo)):\n                        print(f\"  Feature {x}: REDUNDANT \"\n                              f\"(generated by {set(combo)})\")\n                        break\n                else:\n                    continue\n                break\n        else:\n            print(f\"  Feature {x}: ESSENTIAL\")\n\n    # Find skeleton\n    G = set(features)\n    full_cl = feature_cl(frozenset(G))\n    changed = True\n    while changed:\n        changed = False\n        for g in sorted(G):\n            if feature_cl(frozenset(G - {g})) == full_cl:\n                G.remove(g)\n                changed = True\n                break\n\n    print(f\"\\nSelected features (skeleton): {sorted(G)}\")\n    print(f\"Dimension reduction: {len(features)} \u2192 {len(G)}\")\n\n\n# ============================================================\n# Application 3: Network Vulnerability\n# ============================================================\n\ndef network_vulnerability_demo():\n    \"\"\"\n    Network vulnerability analysis via canonical skeletons.\n\n    Scenario: A network of 8 nodes with dependency structure.\n    \"\"\"\n    print(\"\\n\" + \"=\" * 60)\n    print(\"APPLICATION 3: Network Vulnerability Analysis\")\n    print(\"=\" * 60)\n\n    nodes = set(range(8))\n\n    # Network dependencies:\n    # Node 2 depends on {0, 1}\n    # Node 5 depends on {3, 4}\n    # Node 6 depends on {2, 5} (= depends on {0,1,3,4})\n    # Node 7 depends on {6} (= depends on {0,1,3,4})\n    def network_cl(s):\n        s = frozenset(s)\n        result = set(s)\n        changed = True\n        while changed:\n            changed = False\n            if 0 in result and 1 in result and 2 not in result:\n                result.add(2)\n                changed = True\n            if 3 in result and 4 in result and 5 not in result:\n                result.add(5)\n                changed = True\n            if 2 in result and 5 in result and 6 not in result:\n                result.add(6)\n                changed = True\n            if 6 in result and 7 not in result:\n                result.add(7)\n                changed = True\n        return frozenset(result)\n\n    print(f\"\\nNodes: {sorted(nodes)}\")\n    print(f\"\\nDependency rules:\")\n    print(f\"  Node 2 \u2190 {{0, 1}}\")\n    print(f\"  Node 5 \u2190 {{3, 4}}\")\n    print(f\"  Node 6 \u2190 {{2, 5}}\")\n    print(f\"  Node 7 \u2190 {{6}}\")\n\n    # Find skeleton\n    G = set(nodes)\n    full_cl = network_cl(frozenset(G))\n    changed = True\n    while changed:\n        changed = False\n        for g in sorted(G):\n            if network_cl(frozenset(G - {g})) == full_cl:\n                G.remove(g)\n                changed = True\n                break\n\n    print(f\"\\nCritical nodes (skeleton): {sorted(G)}\")\n    print(f\"Redundant nodes: {sorted(nodes - G)}\")\n    print(f\"Full closure of skeleton: {sorted(network_cl(frozenset(G)))}\")\n\n    # Vulnerability analysis: what happens if we remove each critical node?\n    print(\"\\n--- Vulnerability Analysis ---\")\n    for node in sorted(G):\n        remaining = G - {node}\n        reachable = network_cl(frozenset(remaining))\n        lost = nodes - reachable\n        print(f\"  Remove node {node}: lose access to {sorted(lost)} \"\n              f\"({len(lost)} nodes affected)\")\n\n\nif __name__ == \"__main__\":\n    access_structure_demo()\n    feature_selection_demo()\n    network_vulnerability_demo()\n\n    print(\"\\n\" + \"=\" * 60)\n    print(\"All applications demonstrated successfully.\")\n    print(\"=\" * 60)\n"
